/* Small deterministic world. No model-authored physics, social roles or compulsory goals. */
(function(root){
const clone=x=>JSON.parse(JSON.stringify(x)),names=['Ada','Bram','Cleo','Dara','Emil','Fenn'];
function create(seed=42,scarcity='gentle'){return {format:'emergence-world',version:1,seed,scarcity,turn:0,width:12,height:8,agents:names.map((name,i)=>({id:i+1,name,x:4+i%3,y:3+Math.floor(i/3),alive:true,health:100,food:30,water:30,energy:80,memory:[],goal:'',inventory:{food:0,water:0},visited:[],last:'No action yet'})),sites:[{id:'spring',name:'Spring',x:1+(seed%2),y:1,kind:'water',stock:18,capacity:18,renew:scarcity==='scarce'?2:6},{id:'grove',name:'Fruit grove',x:9,y:6-(seed%2),kind:'food',stock:18,capacity:18,renew:scarcity==='scarce'?2:6}],objects:[{id:'jar-1',name:'Clay jar',x:4,y:3,holder:null,water:0,capacity:8},{id:'jar-2',name:'Clay jar',x:6,y:4,holder:null,water:0,capacity:8}],events:[],journal:[]};}
const distance=(a,b)=>Math.abs(a.x-b.x)+Math.abs(a.y-b.y);
function view(s,id){const a=s.agents.find(a=>a.id===id);return {turn:s.turn,self:{id:a.id,name:a.name,position:{x:a.x,y:a.y},health:a.health,food:a.food,water:a.water,energy:a.energy,inventory:clone(a.inventory),goal:a.goal},map:{width:s.width,height:s.height},nearbyPeople:s.agents.filter(b=>b.id!==id&&b.alive&&distance(a,b)<=2).map(b=>({id:b.id,name:b.name,x:b.x,y:b.y})),visibleSites:s.sites.filter(b=>distance(a,b)<=2).map(clone),visibleObjects:s.objects.filter(b=>b.holder===id||b.holder===null&&distance(a,b)<=2).map(clone),memory:clone(a.memory.slice(-12)),sensations:[...(a.food<10?['hungry']:[]),...(a.water<10?['thirsty']:[]),...(a.energy<20?['tired']:[])]};}
function command(v){if(!v||typeof v!=='object'||Array.isArray(v)||Object.keys(v).some(k=>!['kind','target','x','y','amount','speech','goal','note'].includes(k)))throw Error('Invalid command fields');if(!['move','inspect','drink','eat','rest','gather','give','take','drop','fill','pour','wait'].includes(v.kind))throw Error('Unknown action');for(const k of ['speech','goal','note'])if(v[k]!=null&&(typeof v[k]!=='string'||v[k].length>500))throw Error('Invalid text');if(v.amount!=null&&(!Number.isInteger(v.amount)||v.amount<1||v.amount>8))throw Error('Amount must be 1–8');if(v.kind==='move'&&(!Number.isInteger(v.x)||!Number.isInteger(v.y)))throw Error('Movement needs coordinates');return clone(v);}
function step(before,commands,turnId){if(before.journal.some(j=>j.id===turnId))return clone(before);const s=clone(before),events=[],add=(actor,text,kind='action')=>events.push({turn:s.turn+1,actor,kind,text});s.turn++;
// Rotate priority to avoid permanent first-actor advantage over finite shared stock.
const order=s.agents.slice(),shift=(s.turn-1)%order.length;order.push(...order.splice(0,shift));
for(const a of order){if(!a.alive)continue;let c;try{if(!commands[a.id])throw Error('No accepted model action this turn');c=command(commands[a.id]);const amount=c.amount||1,site=s.sites.find(x=>x.id===c.target),object=s.objects.find(x=>x.id===c.target),here=x=>x&&distance(a,x)===0,held=x=>x&&x.holder===a.id;let result='';
if(c.kind==='move'){if(c.x<0||c.y<0||c.x>=s.width||c.y>=s.height)throw Error('Destination is outside the map');let budget=Math.min(2,Math.floor(a.energy/2)),moved=0;while(budget-->0&&(a.x!==c.x||a.y!==c.y)){if(a.x!==c.x)a.x+=Math.sign(c.x-a.x);else a.y+=Math.sign(c.y-a.y);moved++;}a.energy-=moved*2;result='Moved to '+a.x+','+a.y;}
else if(c.kind==='rest'){const gain=Math.min(18,100-a.energy);a.energy+=gain;result='Rest restored '+gain+' energy; it supplied no food or water';}
else if(c.kind==='drink'||c.kind==='eat'){const resource=c.kind==='drink'?'water':'food';let n=0;if(here(site)&&site.kind===resource){n=Math.min(amount,site.stock);site.stock-=n;}else if(resource==='water'&&held(object)){n=Math.min(amount,object.water);object.water-=n;}else {n=Math.min(amount,a.inventory[resource]);a.inventory[resource]-=n;}if(!n)throw Error('No accessible '+resource+'; inspect a site or use carried supplies');a[resource]=Math.min(40,a[resource]+n*5);result='Used '+n+' '+resource+'; restored '+n*5+' reserve units (capacity 40)';}
else if(c.kind==='gather'){if(!here(site))throw Error('Stand at the source to gather');if(site.kind==='water')throw Error('Use fill with a carried jar for transport, or drink here');const n=Math.min(amount,site.stock,8-a.inventory.food);if(!n)throw Error('Source depleted or carrying capacity reached');site.stock-=n;a.inventory.food+=n;result='Gathered '+n+' food';}
else if(c.kind==='take'){if(!here(object)||object.holder!==null)throw Error('Object is not available here');if(s.objects.some(o=>o.holder===a.id))throw Error('One jar per carrier');object.holder=a.id;result='Picked up '+object.id;}
else if(c.kind==='drop'){if(!held(object))throw Error('You are not carrying this object');object.holder=null;object.x=a.x;object.y=a.y;result='Put down '+object.id;}
else if(c.kind==='fill'){if(!held(object))throw Error('Carry the jar first');const source=s.sites.find(x=>here(x)&&x.kind==='water');if(!source)throw Error('Stand at a water source');const n=Math.min(amount,source.stock,object.capacity-object.water);if(!n)throw Error('Jar full or source empty');source.stock-=n;object.water+=n;result='Filled '+object.id+' with '+n+' water';}
else if(c.kind==='give'||c.kind==='pour'){const b=s.agents.find(b=>String(b.id)===String(c.target)&&b.alive);if(!b||distance(a,b)>1||b.id===a.id)throw Error('Recipient must be a living neighbour within one tile');if(c.kind==='give'){const n=Math.min(amount,a.inventory.food,8-b.inventory.food);if(!n)throw Error('No carried food or recipient inventory full');a.inventory.food-=n;b.inventory.food+=n;result='Gave '+n+' food to '+b.name;add(b.id,a.name+' gave me '+n+' food','received');}else{const jar=s.objects.find(o=>o.holder===a.id),n=jar?Math.min(amount,jar.water):0;if(!n)throw Error('No water in a carried jar');jar.water-=n;b.water=Math.min(40,b.water+n*5);result='Poured '+n+' water for '+b.name;add(b.id,a.name+' gave me '+n+' water','received');}}
else if(c.kind==='inspect'){result='Observed: '+JSON.stringify({sites:view(s,a.id).visibleSites,objects:view(s,a.id).visibleObjects,people:view(s,a.id).nearbyPeople});}
else result='Waited';
if(c.goal)a.goal=c.goal;if(c.note)a.memory.push({turn:s.turn,kind:'personal-note',text:c.note});a.last=result;add(a.id,result);
}catch(error){a.last=error.message;add(a.id,error.message,'failed');}
if(c?.speech?.trim()){add(a.id,c.speech,'speech');for(const b of s.agents)if(b.alive&&distance(a,b)<=2)b.memory.push({turn:s.turn,kind:'heard',from:a.name,text:c.speech});}
const own=events.filter(e=>e.actor===a.id&&e.kind!=='speech'&&e.kind!=='received');a.memory.push(...own.map(e=>({turn:s.turn,kind:e.kind,text:e.text})));}
for(const e of events.filter(e=>e.kind==='received'))s.agents.find(a=>a.id===e.actor).memory.push({turn:s.turn,kind:e.kind,text:e.text});
for(const a of s.agents.filter(a=>a.alive)){a.food=Math.max(0,a.food-1);a.water=Math.max(0,a.water-1);a.energy=Math.max(0,a.energy-1);if(!a.food)a.health-=4;if(!a.water)a.health-=6;if(a.health<=0){a.health=0;a.alive=false;add(a.id,a.name+' died','death');}a.visited=[...new Set([...a.visited,a.y*s.width+a.x])];a.memory=a.memory.slice(-40);}
for(const o of s.objects)if(o.holder!==null){const a=s.agents.find(a=>a.id===o.holder);o.x=a.x;o.y=a.y;if(!a.alive)o.holder=null;}
if(s.turn%3===0)for(const site of s.sites){const n=Math.min(site.renew,site.capacity-site.stock);site.stock+=n;if(n)add(null,site.name+' replenished '+n+' '+site.kind,'renewal');}
s.events=[...s.events,...events].slice(-200);s.journal.push({id:turnId,turn:s.turn,commands:clone(commands),events});return s;}
function metrics(s){const events=s.journal.flatMap(j=>j.events);return {turn:s.turn,alive:s.agents.filter(a=>a.alive).length,speech:events.filter(e=>e.kind==='speech').length,transfers:events.filter(e=>e.kind==='received').length,explored:new Set(s.agents.flatMap(a=>a.visited)).size,failures:events.filter(e=>e.kind==='failed').length};}
function replay(initial,journal){return journal.reduce((s,j)=>step(s,j.commands,j.id),clone(initial));}
const api={create,view,command,step,metrics,replay};root.Emergence=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
